BEGIN;

SET LOCAL standard_conforming_strings = on;

INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷九十四", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b3b93bddf1e9a9a2f37c080d778ddb034d0fc54c/content/books/zizhi-tongjian/vol-286/year-0947/part-14/sources/library/jiuwudaishi-094-fang-tai/source.txt", "note": "《旧五代史》卷九十四，段落 jiu-wudaishi-205deb4a7860-p002279；EPUB电子本，纸本及异文待核", "id": "f44e11b4-e4cd-5851-9dd5-c4b0473239be"}, {"title": "宋史·巻四百四十一", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b3b93bddf1e9a9a2f37c080d778ddb034d0fc54c/content/books/zizhi-tongjian/vol-286/year-0947/part-14/sources/library/songshi-441-xu-xuan/source.txt", "note": "《宋史》巻四百四十一，段落 songshi-9c6e46fee832-p071729；EPUB电子本，纸本及异文待核", "id": "ef527188-adc2-5c62-be04-2ded64df6048"}, {"title": "资治通鉴·后汉纪一", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b3b93bddf1e9a9a2f37c080d778ddb034d0fc54c/content/books/zizhi-tongjian/vol-286/year-0947/part-14/sources/library/tongjian-286-947-luoyang-fuzhou-dispositions/source.txt", "note": "《资治通鉴》后汉纪一，段落 zizhi-tongjian-a63549944a71-p003402；电子底本待考，分段待核", "id": "b53f63e9-d3ee-54e7-8e24-93182efcdd0e"}, {"title": "旧五代史·卷九十九", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/df264aefc4373c3f610c2f0bb525ac26f65cd07c/content/books/zizhi-tongjian/vol-286/year-0947/part-13/sources/library/jiuwudaishi-099-heyang-april/source.txt", "note": "《旧五代史》卷九十九，段落 jiu-wudaishi-205deb4a7860-p002430；EPUB电子本，纸本及异文待核", "id": "73d07631-ce73-5399-890a-1e917e6cc33b"}, {"title": "新五代史·卷62·南唐世家·陈觉赴福州", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b581496bddc409a2722727b001b6e1fbe269b9b0/content/books/zizhi-tongjian/vol-285/year-0946/part-02/sources/library/xinwudaishi-062-chen-jue-fuzhou/source.txt", "note": "《新五代史》卷62·南唐世家·陈觉赴福州，段落 xin-wudaishi-b08f244b9241-p003142；已回查上下文与传主，底本原字保留，纸本及异文待核。", "id": "cef07fa0-ebe4-551b-8758-4a3b3e4794b6"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "方太", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：方太，讨平军乱者。", "biography": null, "status": "draft", "id": "f3df25e6-d0a6-57cc-8996-e5d57af4f5ef"}, {"name": "朱乙", "aliases": ["硃乙"], "era": "五代十国", "birth_year": null, "death_year": 947, "description": "后梁嗣密王，曾逃难出家。947年被嵩山首领张遇拥立，随后遭张遇杀害。具体父系和生年尚未核定。", "biography": null, "status": "draft", "id": "40baad1a-0389-5d2c-ad45-3627e47c5e57"}, {"name": "张遇", "aliases": ["張遇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "947年嵩山武装首领，拥立后梁嗣密王朱乙为天子，率众袭击郑州，被方太击退，后杀朱乙请降。与南唐境内的张遇贤分别识别，生卒年未载。", "biography": null, "status": "draft", "id": "993c8408-1ec1-54c9-9555-8b9be4e84d55"}, {"name": "方师朗", "aliases": ["方師朗"], "era": "五代十国", "birth_year": null, "death_year": 947, "description": "方太之子。947年受父亲派遣，向契丹说明情况，被契丹将领麻答杀害。与全师朗（王宗朗）不是同一人。生年未载。", "biography": null, "status": "draft", "id": "08f639af-e9ab-542e-9318-1c65732d9105"}, {"name": "麻答", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹将领，《资治通鉴》称为耶律德光的从弟。944年二月由周儒引导从马家口渡河，攻郓州北津，以接应杨光远。个人其他名字及生卒年本批未核。", "biography": null, "status": "draft", "id": "5911d4cb-fa8a-51ff-a1e4-44450396116a"}, {"name": "刘晞", "aliases": ["劉晞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "涿州人，在契丹曾任枢密使、同平章事及燕京留守。947年任西京留守，到洛阳后责斥奚王慢待赵在礼。与后晋官员刘昫字形、职务不同，暂不合并；生卒年未载。", "biography": null, "status": "draft", "id": "a5949823-5190-5e38-a780-eb04d4e680a5"}, {"name": "潘环", "aliases": ["潘環", "潘瑰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：潘环，王村寨守将、奔梁者。", "biography": null, "status": "draft", "id": "5e093bc1-94d3-542b-ac05-e1f1184aa8ba"}, {"name": "武行德", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "并州榆次人。947年受契丹命运送晋朝铠甲兵器，途中与军士夺取兵器、杀契丹监军，继而占据河阳。生卒年尚未录入。", "biography": null, "status": "draft", "id": "e0ed92f8-edb4-574b-83af-85088429a093"}, {"name": "萧翰", "aliases": ["蕭翰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹将领。946年十一月条下记他与通事刘重进带兵绕到晋军后方，截断粮道及归路，进至栾城接受驻军投降。《资治通鉴》称他是契丹主耶律德光的舅舅，《辽史》保存了不同的亲属说法并质疑相关姓名起源说；具体亲属关系暂待核对。生卒年本批未核。", "biography": null, "status": "draft", "id": "defe15da-7bbc-56ed-9d88-0ec31a88fcaf"}, {"name": "高谟翰", "aliases": ["高謨翰", "高模翰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：高谟翰，契丹前锋将领。", "biography": null, "status": "draft", "id": "70516658-fa9a-5bd1-8a0a-55b9844d4772"}, {"name": "武行友", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "武行德的弟弟。947年受武行德派遣，携蜡封表章经小路前往晋阳。生卒年未载。", "biography": null, "status": "draft", "id": "4b99493b-be61-56ba-9d53-19a33fed5a71"}, {"name": "史弘肇", "aliases": ["史宏肇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "荥泽人，947年二月任刘知远的武节都指挥使，奉命在球场集合各军，宣布出兵日期。《旧五代史》亦有史宏肇的字形。生卒年暂未录入。", "biography": null, "status": "draft", "id": "c36d0d69-d2db-5ee8-9bf6-80791eb21dda"}, {"name": "马诲", "aliases": ["馬誨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉史弘肇所部先锋将领。947年率兵追击契丹军，史弘肇奏报战果。生卒年未载。", "biography": null, "status": "draft", "id": "3a6946e7-e076-5b6f-9988-1f2e07ac9ccf"}, {"name": "耿崇美", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹通事。946年十二月杜重威降后，奉命到易州诱说守军投降，并杀死刺史郭璘。生卒年未载。", "biography": null, "status": "draft", "id": "60458ef5-e4bc-5d29-b338-25090e903595"}, {"name": "崔廷勋", "aliases": ["崔廷勛"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "河内人。947年正月《资治通鉴》称他为大同节度使兼侍中，耶律德光派他率兵看守迁到封禅寺的石重贵及家人。《旧五代史》称为蕃大将崔廷勋，未另建同名人；生卒年未载。", "biography": null, "status": "draft", "id": "43995ba6-a8ce-5d3a-86dd-43d3def50195"}, {"name": "拽剌（西奚王）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "西奚王李绍威的儿子，在父亲去世后继位。耶律德光从上党北归时，他前往迎接并归降。", "biography": null, "status": "draft", "id": "4098a81e-f684-5a3e-a8d7-3bf67a400198"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "陈觉", "aliases": ["陳覺"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：陈觉，海陵人、参与谈议者。", "biography": null, "status": "draft", "id": "8f8c34eb-c238-596f-a688-8b8332b405a1"}, {"name": "冯延鲁", "aliases": ["馮延魯"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冯延巳的弟弟，南唐官员，曾任东都判官、礼部员外郎，与兄长同在元帅府。曾请求允许百姓卖子女；李昪去世后又参与起草包含这一规定的遗诏。生卒年尚未核。", "biography": null, "status": "draft", "id": "a589c28e-c0c5-58bf-989f-96457604ccdd"}, {"name": "江文蔚", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：江文蔚，河南巡官、被勒归者。", "biography": null, "status": "draft", "id": "1ea99141-6047-545a-a073-3cae221091a0"}, {"name": "冯延巳", "aliases": ["馮延巳", "冯延己", "馮延己", "冯延已"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐官员，曾任驾部郎中、齐王元帅府常书记。《资治通鉴》本段作冯延己及延已，《新五代史》作冯延巳；据同一南唐政局、陈觉及常梦锡等对应关系校核为同人，展示采用冯延巳，原文异体保留。生卒年尚未核。", "biography": null, "status": "draft", "id": "0b3ed4d7-1a4c-50a5-ad65-aee4b82089ba"}, {"name": "魏岑", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐齐王府僚属。李昪在位时，常梦锡曾反对他与陈觉、冯延巳等陪侍李璟。生卒年尚未核。", "biography": null, "status": "draft", "id": "58f25557-fd68-5851-90ad-b847734e7dfe"}, {"name": "宋齐丘", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：宋齐丘。", "biography": null, "status": "draft", "id": "313ec6c3-7027-5fef-8b5d-b79d259f9c8a"}, {"name": "徐铉", "aliases": ["徐鉉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "字鼎臣，南唐官员。947年与韩熙载上疏请求处死陈觉、冯延鲁，李璟未采纳。《资治通鉴》此处记会稽，《宋史》记扬州广陵人，籍贯差异保留。生卒年尚未录入。", "biography": null, "status": "draft", "id": "aa3f495d-5349-5093-bee4-984f876430c1"}, {"name": "韩熙载", "aliases": ["韓熙載", "熙载"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：韩熙载，韩叔嗣之子、拟奔吴者。", "biography": null, "status": "draft", "id": "83af8c00-ec9d-5693-9e26-56dc1a5a6a88"}, {"name": "石奉頵", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋宗属，任凤州防御使。947年四月乙亥举凤州归附后蜀。具体亲属连接和生卒年未载。", "biography": null, "status": "draft", "id": "445ddf1f-517e-569d-a4a0-d3b00600df2c"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

